// Original finite teaching examples. Upstream study is recorded in spec 218.
const f=(id,label,answer)=>({id,label,answer});
const item=(id,page,prompt,fields,guidance,hint,example,explanation)=>({id,page,prompt,fields,guidance,hint,example,explanation});
const model=(m,b,title,xUnit,yUnit,comparison)=>({m,b,title,xUnit,yUnit,...(comparison?{comparison}:{} )});
export const linearPages=['Explore','Together','Your turn','Return'];
export const linearRecommendations=[['','Choose if useful'],['signed','Revisit signed numbers'],['fractions','Revisit fractional rates'],['equations','Revisit equations'],['plans','Compare more plans'],['discuss','Discuss a new model']];
export const linearLessons=[
 {id:'zero',title:'1. Across zero',idea:'A negative height tells us which side of a reference platform we are on. It does not mean a negative amount of material.',teach:['Call the platform height 0. Above it is positive; below it is negative. On the number line, going down 2 from 0 reaches −2.','A marker begins 6 height units above the platform. Every second it moves down 2 units: 6, 4, 2, 0, −2, −4, −6. Time is never negative here.','The pair (x, y) names time first, relative height second. At (4, −2), four seconds have passed and the marker is two units below the platform.','Start + signed change × time becomes y = 6 + (−2) × x = 6 − 2x. The signed rate is −2 height units per second.'],model:model('-2','6','Marker height · y = 6 − 2x','seconds','height units'),bridge:'numberline',items:[
 item('guided',1,'Where is the marker after 4 seconds?',[f('height','Relative height y','-2')],['At 3 seconds the marker reaches 0.','One more second moves it down 2: 0 − 2 = −2.'],'Count down in steps of 2 from the starting height 6.','Different example: start at +4 and move down 3 units: +4 − 3 = +1. One more move gives +1 − 3 = −2.','At 4 seconds: 6 − 2 × 4 = −2 height units, below the platform.'),
 item('own',2,'Use the same height rule at 5 seconds.',[f('height','Relative height y','-4')],[],'Find the height at 4 seconds, then move down another 2 units.','Different example: a height starts at +5 and falls 2 each second. At 3 seconds: 5 − 6 = −1. Start this item with its own height 6.','At 5 seconds: 6 − 2 × 5 = −4 height units.'),
 item('return',3,'New context: an elevator starts at floor +3 and goes down 5 floors. What floor does it reach?',[f('floor','Final floor','-2')],['Zero is a reference floor. Negative floors are below it.'],'Move 3 floors down to zero, then continue for the remaining floors.','Different example: start at floor +2, go down 3: +2 − 3 = −1.','+3 − 5 = −2: two floors below the reference floor.') ]},
 {id:'halves',title:'2. Half a step at a time',idea:'A rate can be part of a unit. Two half-unit changes make one whole-unit change.',teach:['Split each height unit into two equal pieces. Each piece is 1/2. From 1 to 3/2 (one and a half) is one half-step; from 3/2 (one and a half) to 2 is another.','A marker starts 1 unit above a datum and rises 1/2 unit each second. At 0, 1, 2 seconds its heights are 1, 3/2, 2.','The height rule is y = (1/2) × x + 1. The rate m is 1/2 height unit per second. The starting height b is 1.','The rate is how much y changes for one extra x. At 4 seconds the height is 3, but the rate is still 1/2.'],model:model('1/2','1','Half-unit marker · y = (1/2)x + 1','seconds','height units'),bridge:'halves',items:[
 item('guided',1,'Name a height and a one-second change.',[f('height','Height at 2 seconds','2'),f('rate','Signed change each second','1/2')],['Two half-unit rises make 1 whole unit.','Starting height 1 + rise 1 = height 2. The one-second change is still 1/2.'],'Separate the total height from the change during just one second.','Different example: start at 2, rise 1/2 each second. After 2 seconds the height is 3; the rate is 1/2.','At 2 seconds the height is 2; each second adds 1/2.'),
 item('own',2,'What height does this marker reach after 5 seconds?',[f('height','Height y','7/2')],[],'Five half-unit rises are 5/2. Add the starting height 1 = 2/2.','Different example: start at 2 and rise 1/2 each second. At 1 second: 2 + 1/2 = 5/2. Use this item’s own start and time.','1 + 5/2 = 2/2 + 5/2 = 7/2 height units (3.5).'),
 item('return',3,'New marker: start at −1/2 height unit and rise 1/2 unit each second for 2 seconds.',[f('height','Final relative height','1/2')],['A negative start is below the datum; a positive rise moves toward and then above it.'],'Two half-unit rises make 1. Add 1 to −1/2.','Different example: −3/2 + 1 = −1/2. Mark both halves on the number line.','−1/2 + (1/2) × 2 = −1/2 + 1 = 1/2.') ]},
 {id:'views',title:'3. Three views, one rule',idea:'A table, a graph and an equation can describe the same steady change and starting value.',teach:['Imagine a net token balance. A balance of −3 means 3 tokens are owed, not that there are negative physical tokens. Each turn adds 2 to the balance.','Start at −3, then add 2 each turn: −3, −1, 1, 3, 5, 7, 9. The table and graph show these same pairs.','Let x mean turns and y mean net token balance. Let m mean change per turn and b mean the balance at x = 0. Here m = 2 and b = −3.','Starting balance + rate × turns is b + m × x. Swapping the two added parts gives m × x + b, or y = 2x − 3. A negative intercept places (0, b) below the horizontal axis.'],model:model('2','-3','Net balance · y = 2x − 3','turns','net tokens'),items:[
 item('guided',1,'Name the two parts of y = m × x + b.',[f('m','Rate m · tokens per turn','2'),f('b','Starting balance b · tokens','-3')],['Read the net balance at x = 0 to find b.','Compare any two neighboring turns to find m.'],'The balance at one turn is −1; the change per turn is +2.','Different example: y = 3x − 1 has rate 3 and starting balance −1.','m = 2 tokens per turn; b = −3 tokens.'),
 item('own',2,'Connect this rule to its table.',[f('height','Net balance at x = 4','5'),f('b','Intercept b','-3')],[],'Multiply the 4 turns by 2, then add the starting balance −3.','Different example: y = 2x − 1 at x = 2 gives 4 − 1 = 3. Its intercept is −1.','At x = 4: 2 × 4 − 3 = 5. At x = 0: b = −3.'),
 item('return',3,'New rule: y = (3/2)x − 1/2. Over two turns it adds 3 tokens. Name its rate and start.',[f('m','Rate m · tokens per turn','3/2'),f('b','Starting balance b · tokens','-1/2')],['Three tokens shared across two equal one-turn changes gives 3/2 per turn.'],'The coefficient of x is the per-turn change. The other term is the value when x = 0.','Different example: y = (1/2)x − 3 has rate 1/2 and starting balance −3.','m = 3/2, b = −1/2. Both a rate and an intercept can be rational numbers.') ]},
 {id:'equal',title:'4. Keep both sides equal',idea:'An equation says two expressions have the same value. Do the same operation to both sides to preserve that equality.',teach:['First solve 2x − 3 = 5. Add 3 to BOTH sides: 2x − 3 + 3 = 5 + 3, so 2x = 8. Divide BOTH sides by 2: x = 4. Substitute: 2 × 4 − 3 = 5.','Now put x on both sides: 2x − 3 = (1/2)x + 3. Subtract (1/2)x from BOTH sides: (3/2)x − 3 = 3, since 2 − 1/2 = 3/2.','Add 3 to BOTH sides: (3/2)x = 6. Divide BOTH sides by 3/2: x = 6 ÷ (3/2) = 4. Four groups of 3/2 make 6.','Check in the original equation: left 2 × 4 − 3 = 5; right (1/2) × 4 + 3 = 5. Equal values confirm this input fits.'],model:model('2','-3','Two sides · y = 2x − 3','input x','value',{m:'1/2',b:'3',title:'Other side · y = (1/2)x + 3'}),items:[
 item('guided',1,'Solve 2x − 3 = 5 in two equal steps.',[f('right','Right side after adding 3 to both sides','8'),f('x','x after dividing both sides by 2','4')],['Add 3 to both sides: 2x = 5 + 3.','Then divide both sides by 2.'],'Changing only one side would break the equality.','Different example: 3x − 2 = 7. Add 2 to both sides: 3x = 9. Divide both by 3: x = 3.','2x = 8, so x = 4. Substitution gives 5 = 5.'),
 item('own',2,'Solve 2x − 3 = (1/2)x + 3. Fill the missing steps.',[f('coefficient','Coefficient after subtracting (1/2)x on both sides','3/2'),f('right','Right side after adding 3 to both sides','6'),f('x','x after dividing by that coefficient','4')],[],'2 − 1/2 = 3/2. Then remove −3 by adding 3 to both sides.','Different example: 3x − 2 = x + 4. Subtract x on both sides: 2x − 2 = 4. Add 2: 2x = 6. Divide by 2: x = 3.','The steps are (3/2)x − 3 = 3; (3/2)x = 6; x = 4. Original sides both equal 5.'),
 item('return',3,'New signed equation: −2x + 6 = 0. Find x.',[f('x','Input x','3')],['Subtract 6 on both sides to get −2x = −6. Divide both sides by −2.'],'How many groups of −2 make −6?','Different example: −3x + 6 = 0 gives −3x = −6, then x = 2.','x = 3: −2 × 3 + 6 = 0.') ]},
 {id:'plans',title:'5. Compare two fee plans',idea:'A starting fee and a rate together determine a total. A greater rate does not always mean a greater total.',teach:['These are invented plans for distances 0–6 km. Plan A starts at 3 coins and adds 3/2 coins per km. Plan B starts at 7 and adds 1/2 per km.','At 2 km: A = 6 and B = 8 coins. At 6 km: A = 12 and B = 10. Which is cheaper changes with distance.','Set the fees equal: 3 + (3/2)x = 7 + (1/2)x. Subtract (1/2)x from BOTH sides: 3 + x = 7. Subtract 3 from BOTH sides: x = 4.','At 4 km both cost 9 coins. Before that meeting point A costs less; after it B costs less, within this model’s domain.'],model:model('3/2','3','Plan A · y = 3 + (3/2)x','km','coins',{m:'1/2',b:'7',title:'Plan B · y = 7 + (1/2)x'}),items:[
 item('guided',1,'How do the plans start and change differently?',[f('start','B starting fee minus A starting fee','4'),f('rate','A rate minus B rate · coins per km','1')],['7 − 3 = 4 coins of starting difference.','3/2 − 1/2 = 1 coin per km of rate difference.'],'Each kilometer closes the starting gap by the difference in rates.','Different example: start gap 6 coins, rate gap 2 coins/km: 6 ÷ 2 = 3 km to close the gap.','The starting gap is 4 coins and the rate difference is 1 coin per km, so they meet at 4 km.'),
 item('own',2,'Where do Plans A and B have equal fees?',[f('x','Distance x · km','4'),f('fee','Fee for EACH plan · coins','9')],[],'Solve the equality, then substitute x into each original plan.','Different example: 1 + 2x = 4 + x gives x = 3 and both fees 7. Use this item’s own rates to verify.','At x = 4: A = 3 + 6 = 9 and B = 7 + 2 = 9 coins.'),
 item('return',3,'New plans: C = 2 + x and D = 5 + (1/2)x, for 0–6 km. At what distance are their fees equal?',[f('x','Equal-fee distance · km','6')],['Subtract (1/2)x and then 2 from BOTH sides.'],'The starting gap is 3 coins; the rate gap is 1/2 coin per km.','Different example: 1 + x = 3 + (1/2)x gives (1/2)x = 2, so x = 4.','2 + x = 5 + (1/2)x gives (1/2)x = 3, so x = 6; both fees are 8 coins.') ]},
 {id:'carry',title:'6. Carry it somewhere new',idea:'Keep the meanings of the quantities while you connect the starting value, rate and equality in a new model.',teach:['This invented stall starts with a net balance of −3 tokens: it owes 3. Each sale adds 3/2 tokens to the net balance. Debt is different from a negative count of objects.','Let x be sales and y be net token balance: y = (3/2)x − 3. Every two sales add 3 tokens. At 0 sales: −3; at 2: 0; at 4: 3.','To reach a balance of 3, solve (3/2)x − 3 = 3. Add 3 to both sides: (3/2)x = 6. Divide both sides by 3/2: x = 4.','Substitute into the starting rule: (3/2) × 4 − 3 = 3. An answer has meaning: four sales give a net balance of three tokens in this model.'],model:model('3/2','-3','Stall net balance · y = (3/2)x − 3','sales','net tokens'),items:[
 item('guided',1,'Name this stall’s rate and starting balance.',[f('m','Rate m · tokens per sale','3/2'),f('b','Starting balance b · tokens','-3')],['Two sales add 3, so one adds 3/2.','The balance at zero sales is −3.'],'Keep the per-sale change separate from what is owed at the start.','Different example: y = (1/2)x − 2 has rate 1/2 and starting balance −2.','m = 3/2 tokens per sale; b = −3 tokens.'),
 item('own',2,'Reach a net balance of 3: (3/2)x − 3 = 3.',[f('right','Right side after adding 3 on both sides','6'),f('x','Number of sales x','4')],[],'After adding 3 to both sides, ask how many groups of 3/2 make 6.','Different example: (1/2)x − 1 = 2 gives (1/2)x = 3, so x = 6.','(3/2)x = 6, so x = 4. Check: (3/2) × 4 − 3 = 3.'),
 item('return',3,'New balances: one is x − 1; another is (1/2)x + 1. At what input are they equal?',[f('x','Equal-balance input x','4')],['Keep the two starting balances and the two rates separate.'],'Subtract (1/2)x from both sides, then add 1 to both sides.','Different example: 2x − 1 = x + 2 gives x − 1 = 2, then x = 3.','(1/2)x − 1 = 1, then (1/2)x = 2, so x = 4. Both new balances equal 3.') ]}
];
